@Component("procedure-handler")
@ProcessingGroup("procedure-processing-group")
public class ProcedureEventHandler {
	
	// core constructor
	ProcedureEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateProcedureEvent
     */
    @EventHandler
    public void handle( CreateProcedureEvent event) {
        entityManager.persist(new Procedure(event.getProcedureId(), event.getProcedureCode(), event.getStartDateTime(), event.getEndDateTime(), event.getEncounter(), event.getPerformer(), event.getProcedureOrder(), event.getStatus()));
    }

    /*
     * @param	event UpdateProcedureEvent
     */
    @EventHandler
    public Procedure handle( UpdateProcedureEvent event) {
    	entityManager.merge(new Procedure(event.getProcedureId(), event.getProcedureCode(), event.getStartDateTime(), event.getEndDateTime(), event.getEncounter(), event.getPerformer(), event.getProcedureOrder(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteProcedureEvent
     */
    @EventHandler
    public void on( DeleteProcedureEvent event) {
    	Procedure entity = new Procedure();
   
    	// ------------------------------------------
    	// apply the ProcedureId
    	// ------------------------------------------
    	entity.setProcedureId( event.getProcedureId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ProcedureRepository procedureEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ProcedureEventHandler.class.getName());

}
